const App: React.FC = () => {
  const [showBottomNav, setShowBottomNav] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Hide preloader after 3 seconds (Improved UX)
    const timer = setTimeout(() => {
      setIsLoading(false);
      document.body.style.overflow = 'auto'; // Re-enable scroll
    }, 3000);

    // Disable scroll when preloader is visible
    document.body.style.overflow = 'hidden';

    return () => {
        clearTimeout(timer);
        document.body.style.overflow = 'auto'; // Ensure scroll is re-enabled on component unmount
    };
  }, []);


  useEffect(() => {
    if (isLoading) return; // Don't run scroll listener while loading

    const handleScroll = () => {
      if (window.scrollY > 300) {
        setShowBottomNav(true);
      } else {
        setShowBottomNav(false);
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [isLoading]);

  return (
    <HashRouter>
      <CursorProvider>
        <AnimatePresence mode="wait">
            {isLoading ? (
            <Preloader key="preloader" />
            ) : (
             <MainContent showBottomNav={showBottomNav} />
            )}
        </AnimatePresence>
      </CursorProvider>
    </HashRouter>
  );
};

