// --- Mouse Following Gradient Hook ---
const useMousePosition = () => {
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  useEffect(() => {
    const updateMousePosition = (ev: MouseEvent) => {
      setMousePosition({ x: ev.clientX, y: ev.clientY });
    };
    window.addEventListener('mousemove', updateMousePosition);
    return () => window.removeEventListener('mousemove', updateMousePosition);
  }, []);
  return mousePosition;
};

// --- Magnetic Particle Background Component ---
const MagneticParticles = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let particles: Particle[] = [];
        let animationFrameId: number;

        const mouse = { x: 0, y: 0, isActive: false };

        const handleMouseMove = (e: MouseEvent) => {
            const rect = canvas.getBoundingClientRect();
            mouse.x = e.clientX - rect.left;
            mouse.y = e.clientY - rect.top;
            mouse.isActive = true;
        };

        const handleMouseLeave = () => {
            mouse.isActive = false;
        }

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseleave', handleMouseLeave);

        class Particle {
            x: number;
            y: number;
            originX: number;
            originY: number;
            size: number;
            color: string;
            vx: number;
            vy: number;
            friction: number;
            ease: number;

            constructor() {
                this.x = Math.random() * canvas!.width;
                this.y = Math.random() * canvas!.height;
                this.originX = this.x;
                this.originY = this.y;
                this.size = Math.random() * 2 + 0.5;
                const colors = ['#22d3ee', '#818cf8', '#a78bfa', '#34d399'];
                this.color = colors[Math.floor(Math.random() * colors.length)];
                this.vx = 0;
                this.vy = 0;
                this.friction = 0.95;
                this.ease = 0.05;
            }

            update() {
                const dx = mouse.x - this.x;
                const dy = mouse.y - this.y;
                const distance = Math.sqrt(dx * dx + dy * dy);
                const forceDistance = 300;

                if (mouse.isActive && distance < forceDistance) {
                    const force = (forceDistance - distance) / forceDistance;
                    const angle = Math.atan2(dy, dx);
                    const moveX = Math.cos(angle) * force * 5; 
                    const moveY = Math.sin(angle) * force * 5;
                    this.vx += moveX;
                    this.vy += moveY;
                }

                this.vx += (this.originX - this.x) * this.ease;
                this.vy += (this.originY - this.y) * this.ease;
                this.vx *= this.friction;
                this.vy *= this.friction;
                this.x += this.vx;
                this.y += this.vy;
            }

            draw() {
                if (!ctx) return;
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
                ctx.fillStyle = this.color;
                ctx.fill();
            }
        }

        const init = () => {
            particles = [];
            const numberOfParticles = (canvas.width * canvas.height) / 8000;
            for (let i = 0; i < numberOfParticles; i++) {
                particles.push(new Particle());
            }
        };

        const resizeCanvas = () => {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
            init();
        };
        window.addEventListener('resize', resizeCanvas);

        const animate = () => {
            if (!ctx) return;
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            particles.forEach(particle => {
                particle.update();
                particle.draw();
            });
            animationFrameId = requestAnimationFrame(animate);
        };

        resizeCanvas();
        animate();

        return () => {
            window.removeEventListener('resize', resizeCanvas);
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseleave', handleMouseLeave);
            cancelAnimationFrame(animationFrameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 pointer-events-none z-[1]" />;
};


// --- Scroll Velocity Component ---
interface ParallaxTextProps {
    children?: React.ReactNode;
    baseVelocity: number;
}

function ParallaxText({ children, baseVelocity = 100 }: ParallaxTextProps) {
    const baseX = useMotionValue(0);
    const { scrollY } = useScroll();
    const scrollVelocity = useVelocity(scrollY);
    const smoothVelocity = useSpring(scrollVelocity, {
        damping: 50,
        stiffness: 400
    });
    const velocityFactor = useTransform(smoothVelocity, [0, 1000], [0, 5], {
        clamp: false
    });

    const x = useTransform(baseX, (v) => `${wrap(-20, -45, v)}%`);

    const directionFactor = useRef<number>(1);
    useAnimationFrame((t, delta) => {
        let moveBy = directionFactor.current * baseVelocity * (delta / 1000);
        if (velocityFactor.get() < 0) directionFactor.current = -1;
        else if (velocityFactor.get() > 0) directionFactor.current = 1;
        moveBy += directionFactor.current * moveBy * velocityFactor.get();
        baseX.set(baseX.get() + moveBy);
    });

    return (
        <div className="overflow-hidden m-0 whitespace-nowrap flex flex-nowrap">
            <motion.div 
                className="font-bold uppercase text-[10vw] md:text-[7vw] leading-[0.85] flex whitespace-nowrap flex-nowrap text-slate-800" 
                style={{ x }}
            >
                <span className="block mr-12">{children} </span>
                <span className="block mr-12">{children} </span>
                <span className="block mr-12">{children} </span>
                <span className="block mr-12">{children} </span>
            </motion.div>
        </div>
    );
}

// --- NEW 3D PROCESS CARD COMPONENT ---
interface ProcessCardProps {
    i: number;
    title: string;
    subtitle: string;
    description: string;
    points: string[];
    icon: React.ReactNode;
    scrollYProgress: MotionValue<number>;
    total: number;
    color: string;
}

const ThreeDProcessCard: React.FC<ProcessCardProps> = ({ i, title, subtitle, description, points, icon, scrollYProgress, total, color }) => {
    const step = useTransform(scrollYProgress, [0, 1], [0, total]);
    const x = useTransform(step, [i - 1, i, i + 1], ['120%', '0%', '-120%']);
    const y = useTransform(step, [i - 1, i, i + 1], ['60%', '0%', '-60%']);
    const scale = useTransform(step, [i - 1, i, i + 1], [0.7, 1, 0.7]);
    const opacity = useTransform(step, [i - 0.6, i - 0.4, i, i + 0.4, i + 0.6], [0, 1, 1, 1, 0]);
    const rotateY = useTransform(step, [i - 1, i, i + 1], [45, 0, -45]);
    const rotateZ = useTransform(step, [i - 1, i, i + 1], [5, 0, -5]);
    const zIndex = useTransform(step, (currentStep) => 100 - Math.round(Math.abs(currentStep - i) * 10));

    return (
        <motion.div 
            style={{ x, y, scale, opacity, rotateY, rotateZ, zIndex, position: 'absolute', perspective: '1500px' }}
            className="w-full max-w-5xl px-4 md:px-0 flex items-center justify-center pointer-events-none"
        >
