                    </div>
                    <h3 className="text-3xl md:text-4xl font-black text-white tracking-tighter uppercase text-center">{title}</h3>
                </div>
                <div className="w-full md:w-2/3 pt-8 md:pt-0 md:pl-12 flex flex-col justify-center relative z-10">
